 88	function parseCookies(header) {
 89	  const cookies = {};
 90	  String(header || '').split(';').forEach((part) => {
 91	    const index = part.indexOf('=');
 92	    if (index < 0) return;
 93	    const key = part.slice(0, index).trim();
 94	    if (!key) return;
 95	    try { cookies[key] = decodeURIComponent(part.slice(index + 1).trim()); } catch (error) { cookies[key] = part.slice(index + 1).trim(); }
 96	  });
 97	  return cookies;
 98	}
