100	function appendCookie(res, text) {
101	  const existing = res.getHeader('Set-Cookie');
102	  const list = existing ? (Array.isArray(existing) ? existing : [String(existing)]) : [];
103	  list.push(text);
104	  res.setHeader('Set-Cookie', list);
105	}
