107	function setCookie(res, name, value, options = {}) {
108	  let text = name + '=' + encodeURIComponent(String(value)) + '; Path=' + (options.path || '/') + '; SameSite=' + (options.sameSite || 'Lax');
109	  if (options.httpOnly !== false) text += '; HttpOnly';
110	  if (options.maxAge !== undefined) text += '; Max-Age=' + Math.floor(Number(options.maxAge));
111	  appendCookie(res, text);
112	}
113	
114	function clearCookie(res, name, options = {}) {
115	  appendCookie(res, name + '=; Path=' + (options.path || '/') + '; Max-Age=0; SameSite=Lax; HttpOnly');
116	}
