118	function readBody(req) {
119	  if (req.__evogitBody) return req.__evogitBody;
120	  req.__evogitBody = new Promise((resolve, reject) => {
121	    const chunks = [];
122	    let size = 0;
123	    req.on('data', (chunk) => {
124	      size += chunk.length;
125	      if (size > MAX_BODY) { reject(new Error('Request body too large')); req.destroy(); return; }
126	      chunks.push(chunk);
127	    });
128	    req.on('error', reject);
129	    req.on('end', () => {
130	      const raw = Buffer.concat(chunks).toString('utf8');
131	      req.rawBody = raw;
132	      if (!raw) { resolve({}); return; }
133	      const type = String(req.headers['content-type'] || '');
134	      if (type.includes('application/x-www-form-urlencoded')) { resolve(Object.fromEntries(new URLSearchParams(raw))); return; }
135	      try { resolve(JSON.parse(raw)); } catch (error) { resolve(type.includes('json') ? {} : { text: raw }); }
136	    });
137	  });
138	  return req.__evogitBody;
139	}
