141	function matcher(req, pathname) {
142	  return function match(method, pattern) {
143	    const wanted = String(method || '*').toUpperCase();
144	    if (wanted !== '*' && wanted !== 'ANY' && wanted !== String(req.method || 'GET').toUpperCase()) return null;
145	    const expected = String(pattern).replace(/\/+$/, '').split('/').filter(Boolean);
146	    const actual = pathname.replace(/\/+$/, '').split('/').filter(Boolean);
147	    const params = {};
148	    for (let index = 0; index < expected.length; index += 1) {
149	      const part = expected[index];
150	      if (part === '*') { params['*'] = actual.slice(index).map(decodeURIComponent).join('/'); return params; }
151	      if (index >= actual.length) return null;
152	      if (part.startsWith(':')) {
153	        try { params[part.slice(1)] = decodeURIComponent(actual[index]); } catch (error) { params[part.slice(1)] = actual[index]; }
154	      } else if (part !== actual[index]) return null;
155	    }
156	    return expected.length === actual.length ? params : null;
157	  };
158	}
