164	async function loadApi() {
165	  ensureDataDir();
166	  if (!fs.existsSync(appModulePath)) return;
167	  hostState.api_present = true;
168	  try {
169	    let loaded = require(appModulePath);
170	    if (loaded && loaded.default && !loaded.handle && typeof loaded !== 'function') loaded = loaded.default;
171	    if (typeof loaded === 'function') loaded = { handle: loaded };
172	    if (!loaded || typeof loaded.handle !== 'function') throw new Error('backend/src/app.js must export handle(req, res, ctx)');
173	    api = loaded;
174	    hostState.api_loaded = true;
175	  } catch (error) {
176	    hostState.api_error = String(error && error.stack ? error.stack : error).slice(0, 4000);
177	    console.error('[host] backend/src/app.js failed to load: ' + hostState.api_error);
178	    return;
179	  }
180	  if (typeof api.init === 'function') {
181	    try { await api.init({ ...sharedContext }); } catch (error) {
182	      hostState.init_error = String(error && error.stack ? error.stack : error).slice(0, 4000);
183	      console.error('[host] app.init failed: ' + hostState.init_error);
184	    }
185	  }
