188	function snapshotData(dir, prefix, out) {
189	  let entries = [];
190	  try { entries = fs.readdirSync(dir, { withFileTypes: true }); } catch (error) { return out; }
191	  for (const entry of entries) {
192	    const full = path.join(dir, entry.name);
193	    const rel = prefix ? prefix + '/' + entry.name : entry.name;
194	    if (entry.isDirectory()) snapshotData(full, rel, out);
195	    else if (entry.isFile() && !entry.name.endsWith('.tmp')) { try { out[rel] = fs.readFileSync(full); } catch (error) { /* skip */ } }
196	  }
197	  return out;
198	}
