200	async function resetApp() {
201	  if (!seedSnapshot) throw new Error('no seed snapshot');
202	  try { fs.rmSync(dataDir, { recursive: true, force: true }); } catch (error) { recordRuntimeError('reset rm', error); }
203	  ensureDataDir();
204	  for (const [rel, content] of Object.entries(seedSnapshot)) {
205	    const target = path.join(dataDir, rel);
206	    fs.mkdirSync(path.dirname(target), { recursive: true });
207	    fs.writeFileSync(target, content);
208	  }
209	  for (const key of Object.keys(require.cache)) {
210	    if (key.startsWith(__dirname + path.sep) && key !== __filename) delete require.cache[key];
211	  }
212	  api = null;
213	  hostState.api_loaded = false;
214	  hostState.api_error = null;
215	  hostState.init_error = null;
