219	function resolveStaticFile(pathname) {
220	  let decoded;
221	  try { decoded = decodeURIComponent(pathname); } catch (error) { return null; }
222	  const candidate = path.resolve(frontendDistPath, decoded.replace(/^\/+/, ''));
223	  if (candidate !== frontendDistPath && !candidate.startsWith(frontendDistPath + path.sep)) return null;
224	  return candidate;
