227	function serveSpa(req, res) {
228	  fs.readFile(path.join(frontendDistPath, 'index.html'), (error, content) => {
229	    if (error) { res.writeHead(503, { 'Content-Type': 'text/html; charset=utf-8' }); res.end(BUILD_MISSING_PAGE); return; }
230	    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-cache' });
231	    res.end(req.method === 'HEAD' ? undefined : content);
232	  });
233	}
