235	function serveStatic(req, res, pathname) {
236	  const filePath = resolveStaticFile(pathname);
237	  if (!filePath) { serveSpa(req, res); return; }
238	  fs.stat(filePath, (error, stats) => {
239	    if (error || !stats.isFile()) {
240	      // Missing hashed assets must not be answered with HTML.
241	      if (/^\/assets\//.test(pathname)) { res.writeHead(404, { 'Content-Type': 'text/plain' }); res.end('Not Found'); return; }
242	      serveSpa(req, res);
243	      return;
244	    }
245	    const type = MIME_TYPES[path.extname(filePath).toLowerCase()] || 'application/octet-stream';
246	    res.writeHead(200, { 'Content-Type': type, 'Content-Length': stats.size, 'Cache-Control': 'no-cache' });
247	    if (req.method === 'HEAD') { res.end(); return; }
248	    fs.createReadStream(filePath).pipe(res);
249	  });
250	}
