252	async function handleApi(req, res, url) {
253	  if (!api) {
254	    if (hostState.api_present) sendJson(res, 500, { error: 'API module failed to load', detail: hostState.api_error });
255	    else sendJson(res, 404, { code: 404, message: 'Not Found' });
256	    return;
257	  }
258	  const ctx = {
259	    ...sharedContext,
260	    method: String(req.method || 'GET').toUpperCase(),
261	    url,
262	    path: url.pathname,
263	    query: url.searchParams,
264	    cookies: parseCookies(req.headers.cookie),
265	    match: matcher(req, url.pathname),
266	  };
267	  try {
268	    const handled = await api.handle(req, res, ctx);
269	    if (!res.writableEnded && !handled) sendJson(res, 404, { code: 404, message: 'Not Found' });
270	  } catch (error) {
271	    recordRuntimeError('handle ' + req.method + ' ' + url.pathname, error);
272	    if (!res.writableEnded) sendJson(res, 500, { error: String(error && error.message ? error.message : error) });
273	  }
274	}
