278	  let url;
279	  try { url = new URL(req.url || '/', 'http://' + host); } catch (error) { sendJson(res, 400, { code: 400, message: 'Bad Request' }); return; }
280	  const pathname = url.pathname;
281	  if (pathname === '/api/health') { sendJson(res, 200, { code: 200, message: 'Backend Ready' }); return; }
282	  if (pathname === '/api/__host') { sendJson(res, 200, hostState); return; }
283	  if (TEST_RESET && pathname === '/api/__evogit_reset' && req.method === 'POST') {
284	    resetApp().then(() => sendJson(res, 200, { ok: true }), (error) => sendJson(res, 500, { error: String(error && error.message || error) }));
